contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // single public test function: include a dummy parameter so the checker treats it as varying input
    function run(uint256 dummy) public payable {
        require(true);

        // observe before-state
        address ownerBefore = c.smartfix_owner(); if (__ESBMC_reverted()) return;
        uint256 balanceBefore = address(c).balance;

        // make the state-changing call on c as a top-level statement and capture revert via try/catch
        bool reverted;
        c.sudicideAnyone(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        // observe after-state
        address ownerAfter = c.smartfix_owner(); if (__ESBMC_reverted()) return;
        uint256 balanceAfter = address(c).balance;

        // General rule: if this contract was not ownerBefore, the call must have reverted and owner and balance unchanged
        assert((address(this) != ownerBefore) ? (reverted && ownerAfter == ownerBefore && balanceAfter == balanceBefore) : true);
    }

    receive() external payable { }
}

